(() => { const screens = document.querySelectorAll('.mobile-screen'); const tabs = document.querySelectorAll('[data-target]'); tabs.forEach(tab => tab.addEventListener('click', () => { const target = tab.dataset.target; screens.forEach(screen => screen.style.display = screen.dataset.screen === target ? 'block' : 'none'); tabs.forEach(item => item.classList.toggle('selected', item === tab)); })); if (new URLSearchParams(location.search).has('probe')) { const probe = document.createElement('output'); probe.id = 'layout-probe'; probe.textContent = `viewport=${innerWidth}x${innerHeight}; document=${document.documentElement.scrollWidth}x${document.documentElement.scrollHeight}; desktop=${getComputedStyle(document.querySelector('.desktop')).display}`; document.body.append(probe); } })();
